import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';


/**
 * Calculate the due date based on payment terms and issue date.
 * @param {string} issueDate in YYYY-MM-DD format
 * @param {string} terms 'NET14', 'NET30', or 'EOM'
 * @returns {string|null} due date in YYYY-MM-DD format, or null if terms invalid
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Get the last day of the month
    const date = new Date(issueDate + 'T00:00:00Z');
    const year = date.getUTCFullYear();
    const month = date.getUTCMonth();

    // Create date for first day of next month
    const nextMonth = new Date(Date.UTC(year, month + 1, 1));
    // Subtract one day to get last day of current month
    nextMonth.setUTCDate(nextMonth.getUTCDate() - 1);

    const day = String(nextMonth.getUTCDate()).padStart(2, '0');
    const monthStr = String(nextMonth.getUTCMonth() + 1).padStart(2, '0');
    const yearStr = nextMonth.getUTCFullYear();

    return `${yearStr}-${monthStr}-${day}`;
  } else {
    return null;
  }
}

/**
 * Calculate the total amount for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} qty × unitPrice in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * VAT is calculated per line on the amount after discount, then rounded per line.
 * Voucher is applied after VAT.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} all in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let totalDiscount = 0;
  let totalVat = 0;

  for (const line of invoice.lines) {
    const lineTotal = line.qty * line.unitPrice;
    const lineDiscount = roundCents(lineTotal * ((line.discountPercent || 0) / 100));
    const lineAmountAfterDiscount = lineTotal - lineDiscount;
    const lineVat = roundCents(lineAmountAfterDiscount * (line.vatRate / 100));

    subtotal += lineTotal;
    totalDiscount += lineDiscount;
    totalVat += lineVat;
  }

  const discount = Math.max(0, totalDiscount);
  const vat = Math.max(0, totalVat);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);

  return { subtotal, discount, vat, voucher, total };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ status: string, customerId: string, lines: Array }} invoice
 * @param {{ sku: string, qty: unknown, discountPercent?: unknown }} input
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

