import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';
import { lineTotal, invoiceTotals } from './totals.js';

// Re-export for backwards compatibility
export { lineTotal, invoiceTotals } from './totals.js';


/**
 * Calculate the due date based on payment terms and issue date.
 * @param {string} issueDate in YYYY-MM-DD format
 * @param {string} terms 'NET14', 'NET30', or 'EOM'
 * @returns {string|null} due date in YYYY-MM-DD format, or null if terms invalid
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Get the last day of the month
    const date = new Date(issueDate + 'T00:00:00Z');
    const year = date.getUTCFullYear();
    const month = date.getUTCMonth();

    // Create date for first day of next month
    const nextMonth = new Date(Date.UTC(year, month + 1, 1));
    // Subtract one day to get last day of current month
    nextMonth.setUTCDate(nextMonth.getUTCDate() - 1);

    const day = String(nextMonth.getUTCDate()).padStart(2, '0');
    const monthStr = String(nextMonth.getUTCMonth() + 1).padStart(2, '0');
    const yearStr = nextMonth.getUTCFullYear();

    return `${yearStr}-${monthStr}-${day}`;
  } else {
    return null;
  }
}

/**
 * Calculate the total amount for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} qty × unitPrice in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * VAT is calculated per line on the amount after discount, then rounded per line.
 * Voucher is applied after VAT.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} all in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let totalDiscount = 0;
  let totalVat = 0;

  for (const line of invoice.lines) {
    const lineTotal = line.qty * line.unitPrice;
    const lineDiscount = roundCents(lineTotal * ((line.discountPercent || 0) / 100));
    const lineAmountAfterDiscount = lineTotal - lineDiscount;
    const lineVat = roundCents(lineAmountAfterDiscount * (line.vatRate / 100));

    subtotal += lineTotal;
    totalDiscount += lineDiscount;
    totalVat += lineVat;
  }

  const discount = Math.max(0, totalDiscount);
  const vat = Math.max(0, totalVat);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);

  return { subtotal, discount, vat, voucher, total };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ status: string, customerId: string, lines: Array }} invoice
 * @param {{ sku: string, qty: unknown, discountPercent?: unknown }} input
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

  const product = getProduct(sku);
  if (!product.ok) {
    return product;
  }

  const customer = getCustomer(invoice.customerId);
  const tierDiscount = customer.ok ? TIER_DISCOUNTS[customer.value.tier] || 0 : 0;

  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    newLines = invoice.lines.map((line, index) => {
      if (index === existingLineIndex) {
        return {
          ...line,
          qty: line.qty + qty,
          discountPercent: discountPercent !== undefined ? discountPercent : line.discountPercent,
        };
      }
      return { ...line };
    });
  } else {
    newLines = [
      ...invoice.lines.map((line) => ({ ...line })),
      {
        sku,
        name: product.value.name,
        qty,
        unitPrice: product.value.unitPrice,
        vatRate: product.value.vatRate,
        discountPercent: discountPercent !== undefined ? discountPercent : tierDiscount,
      },
    ];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku).map((line) => ({ ...line }));

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: { status: string, number: string, lines: Array } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: { code: string } }} invoice
 * @param {{ code: string, amount: unknown }} input
 * @returns {{ ok: true, value: { status: string, voucher: { code: string, amount: number } } } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

/**
 * Create a draft invoice with the given customer and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: unknown }>, terms?: string }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  const dueDate = calculateDueDate(issueDate, terms);
  if (!dueDate) {
    return fail('TERMS_INVALID');
  }

  const normalizedCustomerId = normalizeId(customerId);
  const customer = getCustomer(normalizedCustomerId);
  if (!customer.ok) {
    return customer;
  }

  if (!lines || lines.length === 0) {
    return fail('NO_LINES');
  }

  const tierDiscount = TIER_DISCOUNTS[customer.value.tier] || 0;

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    if (line.discountPercent !== undefined) {
      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    }

    const product = getProduct(line.sku);
    if (!product.ok) {
      return product;
    }

    invoiceLines.push({
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
      discountPercent: line.discountPercent !== undefined ? line.discountPercent : tierDiscount,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

